head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vDigitalYn = "N";
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // fn_getParam();
        scwin.isDigitalYn();
        scwin.getParentValue();

        // 가우스헤더 셋팅
        // dts_StudyCond.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLSTUDYCOND_IN";
        // dts_StudyCond.reset();

        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10006.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_DsclAcptListAll_OnDblClick
 * @description grd_DsclAcptListAll 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
