 */
scwin.grd_DsclAcptListAll_OnDblClick = async function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            await $c.stf.openDisclViewer(scwin.gAcptNo, "R");
            /*
            var url = "/dsclproc/ULDSTF10001.gfm?"
            		+"gAcptNo="+gAcptNo
            		+"&gViewerStat=R";
            var winTitle ="공시뷰어";

            //alert(" frame.FrameID="+ frame.FrameID);
            if (frame.Provider("/top") != undefined) {
                //frame.Provider("/top").WinOpen("viewer"+gAcptNo,  url+"?" + frame.FrameID,winTitle, 1000, 800);
            	frame.Provider("/top").WinOpen("viewer"+gAcptNo,  url,winTitle, 1000, 800);

            } else {
                //frame.CreateFrame("viewer"+gAcptNo,url+"?" + frame.FrameID , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);
            	frame.CreateFrame("viewer"+gAcptNo,url+"?" + frame.FrameID+"&gAcptNo="+gAcptNo , winTitle ,10, 10, 1000, 800, "window" , 0, 0, true);
            }
             */

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10006.grd_DsclAcptListAll_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_DsclAcptListAll_OnLoadError
 * @description dts_DsclAcptListAll 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclAcptListAll_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_DsclAcptListAll);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10006.dts_DsclAcptListAll_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclAcptListAll_OnLoadCompleted
 * @description dts_DsclAcptListAll 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_DsclAcptListAll_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_DsclAcptListAll.errorMsg) {
            await $c.win.alert(dts_DsclAcptListAll.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page); // 총 건수

        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10006.dts_DsclAcptListAll_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF10006.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF10006.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_DsclAcptListAll, {fileName: "제출보고서 목록", type: "2"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF10006.btn_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 화면 로딩시 디폴트 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    let url = "";
    if (scwin.vDigitalYn === "Y") {
        url = "/digital/DisclsSearch.do?method=listDigitalAllDsclAcptIsur&inputMessageId=ALLDSCLISUR_IN";
    } else {
    }
    url += "&outputMessageId=ALLDSCLISUR_OUT" + "&ISUR_CD=" + scwin.gIsurCd + "&SCREN_ID=" + 'ULDSTF10006.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_DsclAcptListAll",
        action : "/DisclosureSearch.do",
        ref : "",
        target : "dts_DsclAcptListAll=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParentValue = function() {
    // gAcptNo = frame.Provider("../").gAcptNo;
    // gMainFormCd = frame.Provider("../").gMainFormCd;
    // gFormVer = frame.Provider("../").gFormVer;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    // alert("회사코드:"+gIsurCd);

    if (typeof(scwin.gIsurCd) === 'undefined') {
        scwin.getParam();
    }
};

/**
 * @method
 * @name getParam
 * @description get Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.getParam = function() {
    let pvd = scwin.getProvider();
    let Temp0 = pvd.split("&")[0];
    scwin.gIsurCd = Temp0.split("=")[1];
};

/**
 * @method
 * @name isDigitalYn
 * @description is Digital Yn 처리
 * @returns {void}
 * @hidden N
 */
scwin.isDigitalYn = function() {
    let pvd = scwin.getProvider();
    if (pvd !== undefined && pvd !== null && pvd.length > 1) {
        let Temp0 = pvd.split("&")[1];
        if (Temp0 !== null && Temp0 !== undefined && Temp0.length > 1) {
            const digitalYn = Temp0.split("=")[1];
            if (pvd !== null && digitalYn === "Y") {
                scwin.vDigitalYn = "Y";
            }
        }
    }
};

/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    const arr = url.split("?")[1];
    // alert( url);

    if (typeof(arr) !== 'undefined') {
        return (arr.length >= 1 ? arr : undefined);
    } else {
        return 'undefined';
    }
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclAcptListAll.getCellData(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclAcptListAll.getCellData(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclAcptListAll.getCellData(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclAcptListAll.getCellData(Number(obj), "ISUR_CD");

    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);

};
